from pathlib import Path
import json, base64, io
from PIL import Image

ROOT = Path(__file__).resolve().parents[2]
data = json.loads((ROOT / "prototype/body-localization/results.json").read_text())
f = data["frames"][0]


def photo(name):
    p = ROOT / "prototype/stone-accuracy/frames" / name
    im = Image.open(p)
    im.thumbnail((1280, 720))
    b = io.BytesIO()
    im.convert("RGB").save(b, format="JPEG", quality=88)
    return "data:image/jpeg;base64," + base64.b64encode(b.getvalue()).decode()


rows = []
for l in f["labels"]:
    p = f["predictions"][l["prediction_index"]]
    rows.append(
        {
            "id": l["id"],
            "colour": l["colour"],
            "reference": l["reference_m"],
            "corrected": l["predicted_metric_m"],
            "raw": p["uncorrected_diagram_m"],
        }
    )
